import { KsInlineAlert } from '.';
import { ItemType } from './types';

export const InternalRenderDynamicSlots = (
  props: Partial<KsInlineAlert>,
  wrapWithSlot: (slotName: string, children: unknown) => unknown,
) => {
  const renderedNodes: unknown[] = [];
  const pushRenderedNode = (item: ItemType, index: number) => {
    if (typeof item.content === 'function') {
      renderedNodes.push(wrapWithSlot(`slot-content-${item.key ?? index}`, item.content()));
    } else if (item.content) {
      renderedNodes.push(wrapWithSlot(`slot-content-${item.key ?? index}`, item.content));
    }

    if (typeof item.actions === 'function') {
      renderedNodes.push(wrapWithSlot(`slot-actions-${item.key ?? index}`, item.actions()));
    } else if (item.actions) {
      renderedNodes.push(wrapWithSlot(`slot-actions-${item.key ?? index}`, item.actions));
    }
  };
  props.items?.forEach?.(pushRenderedNode);

  return renderedNodes;
};
