import {
  Component,
  h,
  Prop,
  EventEmitter,
  Event,
  Watch,
  State,
  ComponentInterface,
  Host,
  Element,
  Fragment,
} from '@stencil/core';
import { ks } from '@fe-infra/keystone-design-tokens';
import { Slot, Slots } from '@src/framework/decorators';
import { InlineAlertVariant, InfoOrientation, ItemType, InfoSize } from './types';
import { registerPluginManager } from '@src/shared/unclassified/plugin';
import { createOpenCloseMotion } from '@src/shared/animation';
import { sendActionTracking } from '@src/shared/unclassified/tracking';
import { InternalRenderDynamicSlots } from './utils';
import {
  KsIconChevronDown,
  KsIconClose,
  KsIconFilledCaution,
  KsIconFilledCheck,
  KsIconFilledInfo,
  KsIconFilledLightbulb,
  KsIconFilledWarning,
} from '@fe-infra/keystone-icons-stencil';

const prefix = 'inline-alert';
const DIVIDER_VARIANT = 'neutral';

const getIcon = (variant: string) => {
  switch (variant) {
    case 'success':
      return <KsIconFilledCheck innerColor={ks.color.success.onFillLow} />;
    case 'warning':
      return <KsIconFilledWarning innerColor={ks.color.warning.onFillLow} />;
    case 'error':
      return <KsIconFilledCaution innerColor={ks.color.error.onFillLow} />;
    case 'support':
      return <KsIconFilledLightbulb innerColor={ks.color.support.onFillLow} />;
    default:
      return <KsIconFilledInfo innerColor={ks.color.primary.onFillLow} />;
  }
};

/**
 * @slot title - Allows customization of the title area of the inline-alert.
 * @slot content - The main content section that displays the alert message text.
 * @slot actions - Allows customization of the actions area of the inline-alert.
 * @slot icon - Allows customization of the icon displayed in the inline-alert.
 * @slot closeIcon - Allows customization of the close icon.
 * @part content - The content container.
 * @part actions - The actions container.
 * @part frame - The outer frame that wraps the alert surface.
 * @part base - The base container of the component.
 * @part body - The body container.
 * @part title - The title element.
 */
@Component({
  tag: 'ks-inline-alert',
  styleUrl: 'index.scss',
  shadow: true,
})
export class KsInlineAlert implements ComponentInterface {
  @Element() el!: HTMLKsInlineAlertElement;
  /** The visual variant of the inline-alert. Possible values include `"info"`, `"warning"`, `"error"`, `"success"`, and `"suggestion"`. */
  @Prop() variant: InlineAlertVariant = 'info';
  /** Applies the inverse style for use on darker surfaces. */
  @Prop() inverse = false;
  /** Controls whether the inline-alert is visible. When undefined, the component manages its own open state. */
  @Prop() open?: boolean;
  /** Controls whether the leading status icon is displayed. */
  @Prop() showIcon = true;
  /** Controls the density of the inline-alert. Use `md` for the default size or `sm` for a compact layout. */
  @Prop() size: InfoSize = 'md';
  /** Controls whether the inline-alert shows a dismiss button. */
  @Prop() closeable = true;
  /** Controls whether open and close state changes animate. */
  @Prop() animation = true;
  /** The title text displayed at the top of the inline-alert. */
  @Prop() title = '';
  /** The main message content displayed inside the inline-alert. */
  @Prop() content?: string;
  /** An array of sections to render inside the inline-alert. Each item can provide its own `content`, `actions`, and `key`. */
  @Prop() items: ItemType[] = [];
  /**
   * Indicates whether to show the "View more/less" functionality. When `true`, a "View more/less" link will be displayed if there is collapsible content. \
   * Please note that this feature **ONLY** works when `orientation` is set to `vertical`.
   */
  @Prop() collapsible = false;
  /**
   * Indicates whether the inline-alert content is collapsed. \
   * When `true`, the collapsible part of the inline-alert content will be hidden, has higher priority than default collapsing behavior.
   */
  @Prop() collapsed?: boolean;
  /** Controls whether the inline-alert lays out its content horizontally or vertically. When `items` is provided, the layout is always vertical. */
  @Prop() orientation: InfoOrientation = 'vertical';
  /** Callback invoked after the inline-alert finishes closing and is hidden. */
  @Prop() afterClose?: () => void;
  /** Triggered when the user activates the close button. */
  @Event({ bubbles: false, composed: false }) ksClose!: EventEmitter<void>;
  /** Triggered when the collapsed state changes. Emits the next collapsed value. */
  @Event({ bubbles: false, composed: false }) ksCollapseChange!: EventEmitter<boolean>;

  /** The title of the inline-alert, which is displayed prominently at the top. */
  @Slot({ slotname: 'title' }) private titleSlot?: Slots;
  /** The actions area of the inline-alert, which is displayed prominently at the end. */
  @Slot({ slotname: 'actions' }) private actionSlot?: Slots;

  @Slot({ slotname: 'content' }) private contentSlot?: Slots;

  // @Slot({ slotname: 'icon' }) private iconSlot?: Slots;

  /** 控制动画显隐 */
  @State() _open: boolean = this.open ?? true;
  @State() _collapsed = false;

  private openAnimation = createOpenCloseMotion();

  @Watch('open')
  async handleWatch(val: boolean) {
    if (!this.animation) {
      this.openAnimation.cancel();
      this._open = val;
      return;
    }

    await this.openAnimation.height(this.el, val, {
      duration: 200,
      beforeOpen: () => (this._open = true),
      afterOpen: () => (this._open = true),
      afterClose: () => {
        this._open = false;
        this.afterClose?.();
      },
    });
  }

  @Watch('collapsed')
  handleCollapse() {
    if (this.collapsed !== undefined) this._collapsed = this.collapsed;
  }

  constructor() {
    registerPluginManager(this.el);
  }

  private handleClose = () => {
    // presented open has higher priority
    if (this.open === undefined) {
      this._open = false;
    }
    // still triggers the close event
    this.ksClose.emit();
    sendActionTracking(this.el, { eventType: 'close' });
  };

  private handleCollapseChange = () => {
    const triggerValue = !this._collapsed;
    // presented collapsed has higher priority
    if (this.collapsed === undefined) {
      this._collapsed = !this._collapsed;
    }
    // still triggers the collapse change event
    this.ksCollapseChange.emit(triggerValue);

    try {
      const text = this.actionSlot?.map((item) => item.textContent).join('\n');
      sendActionTracking(this.el, {
        eventType: 'click',
        componentParams: { text },
      });
    } catch (error) {
      // ignore error
    }
  };

  // eslint-disable-next-line @stencil-community/own-methods-must-be-private
  static __internal_renderDynamicSlots(
    props: Partial<KsInlineAlert>,
    wrapWithSlot: (slotName: string, children: unknown) => unknown,
  ) {
    return InternalRenderDynamicSlots(props, wrapWithSlot);
  }

  componentWillLoad(): void {
    this._open = this.open ?? true;
    this._collapsed = this.collapsed ?? false;
  }

  disconnectedCallback() {
    this.openAnimation.dispose();
  }

  // TODO restructure and remove the suppression of max-lines warning
  // eslint-disable-next-line max-lines-per-function
  render() {
    const variant = this.variant === 'info' ? 'primary' : this.variant === 'suggestion' ? 'support' : this.variant;
    const multiLayout = this.items.length > 0;
    const orientation = this.items.length > 0 ? 'vertical' : this.orientation;
    const isVertical = orientation === 'vertical';
    const leftFrameCls = {
      [`${prefix}__frame`]: true,
      [`${prefix}--${variant}_frame-normal`]: !this.inverse,
      [`${prefix}--${variant}_frame-inverse`]: this.inverse,
    };
    const contentCls = {
      [prefix]: true,
      [`${prefix}--${orientation}`]: true,
      [`${prefix}--${this.inverse ? 'inverse' : 'normal'}`]: true,
      [`${prefix}--${variant}`]: true,
      [`${prefix}--compact`]: this.size === 'sm',
    };
    const content = multiLayout ? (
      <div class={{ ['content']: true, ['content-close']: this._collapsed }}>
        <div class={{ ['content-container']: true, ['content-container-close-multiple']: this._collapsed }}>
          {this.items.map((info, index) => (
            <Fragment>
              {info.content && (
                <div
                  class={{
                    [`${prefix}__body-content`]: true,
                    [`${prefix}__body-content-no_title`]: (this.titleSlot && index === 0) || false,
                  }}
                  part="content"
                >
                  <slot name={`slot-content-${info.key ?? index}`}></slot>
                </div>
              )}
              {info.actions && (
                <div class={`${prefix}__body-actions`} part="actions">
                  <slot name={`slot-actions-${info.key ?? index}`}></slot>
                </div>
              )}
              {(index !== this.items.length - 1 || this.collapsible) && <ks-divider variant={DIVIDER_VARIANT} />}
            </Fragment>
          ))}
        </div>
        {this.collapsible && (
          <div class={`${prefix}__actions`} part="actions">
            <slot name="actions">
              <ks-link onClick={this.handleCollapseChange} data-testid="ks-inline-alert-index-4FuCAx">
                <span
                  class={{ [`${prefix}__actions-view`]: true, [`${prefix}__actions-view-rotate`]: !this._collapsed }}
                >
                  View {this._collapsed ? 'more' : 'less'}
                  <KsIconChevronDown class={'chevron'} size={14}></KsIconChevronDown>
                </span>
              </ks-link>
            </slot>
          </div>
        )}
      </div>
    ) : (
      <Fragment>
        {(this.contentSlot || typeof this.content === 'string' || typeof this.content === 'number') && (
          <div
            class={{
              ['content-container-close']: this._collapsed,
              [`${prefix}__body-content`]: true,
            }}
            part="content"
          >
            <slot name="content">{this.content}</slot>
          </div>
        )}
        {this.actionSlot && (!this.collapsible || !isVertical) && (
          <div class={`${prefix}__actions--horizontal`} part="actions">
            <slot name="actions"></slot>
          </div>
        )}
        {this.collapsible && (
          <div class={`${prefix}__actions`} part="actions">
            <ks-link onClick={this.handleCollapseChange} data-testid="ks-inline-alert-index-mQ4tVh">
              <slot name="actions">
                <span
                  class={{ [`${prefix}__actions-view`]: true, [`${prefix}__actions-view-rotate`]: !this._collapsed }}
                >
                  View {this._collapsed ? 'more' : 'less'}
                  <KsIconChevronDown class={'chevron'} size={14}></KsIconChevronDown>
                </span>
              </slot>
            </ks-link>
          </div>
        )}
      </Fragment>
    );

    return (
      <Host class="KsInlineAlert" role="alert" hidden={!this._open}>
        {this._open ? (
          <div class={leftFrameCls} part="frame">
            <div class={contentCls} part="base">
              {this.showIcon && (
                <div class={`${prefix}__icon ${this.titleSlot ? `${prefix}__icon-title` : ``}`}>
                  <slot name="icon">{getIcon(variant)}</slot>
                </div>
              )}
              <div
                class={`${prefix}__body ${this.size === 'sm' && isVertical ? `${prefix}__body-compact` : ''}`}
                part="body"
              >
                {this.titleSlot && (
                  <div class={`${prefix}__body-title`} part="title">
                    <slot name="title"></slot>
                  </div>
                )}
                {content}
              </div>
              {this.closeable && (
                <div class={`${prefix}__close`} onClick={this.handleClose} data-testid="ks-inline-alert-index-iQPhqh">
                  <ks-icon-button variant="text" size="xs">
                    <slot name="closeIcon">
                      <KsIconClose size="14" />
                    </slot>
                  </ks-icon-button>
                </div>
              )}
            </div>
          </div>
        ) : null}
      </Host>
    );
  }
}
